out=[]
for i,g in enumerate(groups,1):
 matches=[r for r in rows if r['inn']==g[1] and r['company']==g[2] and r['date']+' №'+r['number'] in g[4]]
 assert len(matches)==g[5],(i,len(matches),g[5])
 assert sum(r['amount_cents'] for r in matches)==round(g[6]*100)
 closed=[r for r in matches if not r['flags']]
 status='Платежи привязаны' if len(closed)==len(matches) else ('Часть платежей привязана' if closed else ('Счёт найден; объект открыт' if i in (18,21) else 'Документ/объект пока не подтверждён'))
 note=notes.get(i,'Совпадающий оплаченный документ в проверенных источниках не подтверждён. Не означает, что документ отсутствует; запроса пользователю пока нет.')
 latest_links=json.loads((ROOT/'evidence/continuation_oct6/new_links.json').read_text()) if (ROOT/'evidence/continuation_oct6/new_links.json').exists() else []
 latest_notes=[x['evidence'] for x in latest_links if x['operation_id'] in {r['id'] for r in matches}]
 if latest_notes:note='; '.join(dict.fromkeys(latest_notes))
 sources='; '.join(dict.fromkeys(r.get('crm_evidence','') for r in matches if r.get('crm_evidence')))
 out.append(dict(group=i,supplier=g[0],inn=g[1],company=g[2],reference=g[3],payments=g[4],amount=g[6],status=status,result=note,checks=checks,boundary=boundary,evidence=sources,operation_ids=[r['id'] for r in matches],user_action='Не запрашивается'))
(E/'review_results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
wb=Workbook();wb.remove(wb.active)
counts=collections.Counter(x['status'] for x in out)
